import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.plugin.MojoFailureException;

import javax.tools.Diagnostic;
import javax.tools.DiagnosticCollector;
import javax.tools.JavaCompiler;
import javax.tools.JavaFileObject;
import javax.tools.StandardJavaFileManager;
import javax.tools.ToolProvider;
import java.io.File;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.Charset;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

/**
 * Minimal stand-in for maven-compiler-plugin:compile, backed by the JDK's
 * system Java compiler.
 */
public class CompileMojo extends AbstractMojo {

    private File basedir;
    private File outputDirectory;
    private List<String> classpathElements;
    private List<String> compileSourceRoots;
    private String release;
    private String encoding;

    @Override
    public void execute() throws MojoExecutionException, MojoFailureException {
        List<String> roots = compileSourceRoots;
        if (roots == null || roots.isEmpty()) {
            roots = List.of(new File(basedir, "src/main/java").getPath());
        }
        outputDirectory.mkdirs();
        List<File> sources = collectJavaSources(roots);
        if (sources.isEmpty()) {
            getLog().info("No sources to compile");
            return;
        }
        getLog().info("Compiling " + sources.size() + " source files to " + outputDirectory);
        compile(sources, outputDirectory, classpathElements, release, encoding, getLog());
    }

    static List<File> collectJavaSources(List<String> roots) throws MojoExecutionException {
        List<File> sources = new ArrayList<>();
        for (String root : roots) {
            Path rootPath = new File(root).toPath();
            if (!Files.isDirectory(rootPath)) {
                continue;
            }
            try (Stream<Path> walk = Files.walk(rootPath)) {
                walk.filter(Files::isRegularFile)
                        .filter(p -> p.toString().endsWith(".java"))
                        .forEach(p -> sources.add(p.toFile()));
            } catch (IOException e) {
                throw new MojoExecutionException("Failed to scan source directory " + root, e);
            } catch (UncheckedIOException e) {
                throw new MojoExecutionException("Failed to scan source directory " + root, e.getCause());
            }
        }
        return sources;
    }

    static void compile(List<File> sources, File outputDirectory, List<String> classpathElements,
                        String release, String encoding, org.apache.maven.plugin.logging.Log log)
            throws MojoFailureException, MojoExecutionException {
        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
        if (compiler == null) {
            throw new MojoExecutionException("No system Java compiler available (JDK required)");
        }
        Charset charset = Charset.forName(encoding == null || encoding.isEmpty() ? "UTF-8" : encoding);
        DiagnosticCollector<JavaFileObject> diagnostics = new DiagnosticCollector<>();
        List<String> options = new ArrayList<>();
        options.add("-d");
        options.add(outputDirectory.getAbsolutePath());
        if (classpathElements != null && !classpathElements.isEmpty()) {
            options.add("-cp");
            options.add(String.join(File.pathSeparator, classpathElements));
        }
        if (release != null && !release.isEmpty()) {
            options.add("--release");
            options.add(release);
        }
        options.add("-parameters");
        options.add("-encoding");
        options.add(charset.name());
        try (StandardJavaFileManager fileManager =
                     compiler.getStandardFileManager(diagnostics, null, charset)) {
            Iterable<? extends JavaFileObject> units = fileManager.getJavaFileObjectsFromFiles(sources);
            boolean success = compiler.getTask(null, fileManager, diagnostics, options, null, units).call();
            if (!success) {
                StringBuilder message = new StringBuilder("COMPILATION ERROR\n");
                for (Diagnostic<? extends JavaFileObject> diagnostic : diagnostics.getDiagnostics()) {
                    if (diagnostic.getKind() == Diagnostic.Kind.ERROR) {
                        message.append(diagnostic.getSource() == null ? "" : diagnostic.getSource().getName())
                                .append(':').append(diagnostic.getLineNumber())
                                .append(' ').append(diagnostic.getMessage(null)).append('\n');
                    }
                }
                throw new MojoFailureException(message.toString());
            }
        } catch (IOException e) {
            throw new MojoExecutionException("Compilation failed: " + e, e);
        }
    }
}
