  "content": "package shim.maven;

import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.project.MavenProject;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.jar.Attributes;
import java.util.jar.JarEntry;
import java.util.jar.JarOutputStream;
import java.util.jar.Manifest;
import java.util.stream.Stream;

/**
 * Minimal stand-in for maven-jar-plugin:jar. Packages the main output
 * directory into target/<finalName>.jar and attaches it as the project
 * artifact so spring-boot:repackage can find it.
 */
public class JarMojo extends AbstractMojo {

    private MavenProject project;
    private File outputDirectory;
    private File buildDirectory;
    private String finalName;

    @Override
    public void execute() throws MojoExecutionException {
        buildDirectory.mkdirs();
        File jarFile = new File(buildDirectory, finalName + ".jar");
        getLog().info("Building jar: " + jarFile.getAbsolutePath());
        Manifest manifest = new Manifest();
        Attributes attributes = manifest.getMainAttributes();
        attributes.putValue("Manifest-Version", "1.0");
        attributes.putValue("Created-By", "maven-jar-plugin 3.3.0");
        attributes.putValue("Build-Jdk-Spec", System.getProperty("java.specification.version", ""));
        try (JarOutputStream jos = new JarOutputStream(new FileOutputStream(jarFile), manifest)) {
            Path base = outputDirectory.toPath();
            if (Files.isDirectory(base)) {
                try (Stream<Path> walk = Files.walk(base)) {
                    walk.filter(Files::isRegularFile).forEach(p -> {
                        String name = base.relativize(p).toString().replace(File.separatorChar, '/');
                        try {
                            JarEntry entry = new JarEntry(name);
                            entry.setTime(Files.getLastModifiedTime(p).toMillis());
                            jos.putNextEntry(entry);
                            Files.copy(p, jos);
                            jos.closeEntry();
                        } catch (IOException e) {
                            throw new UncheckedIOException(e);
                        }
                    });
                }
            }
        } catch (UncheckedIOException e) {
            throw new MojoExecutionException("Failed to build jar: " + e.getCause(), e.getCause());
        } catch (IOException e) {
            throw new MojoExecutionException("Failed to build jar: " + e, e);
        }
        project.getArtifact().setFile(jarFile);
    }
}
