package com.instanceguard.platform.config;

import com.instanceguard.platform.entity.User;
import com.instanceguard.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final PasswordEncoder passwordEncoder;

    public DataInitializer(UserMapper userMapper, PasswordEncoder passwordEncoder) {
        this.userMapper = userMapper;
        this.passwordEncoder = passwordEncoder;
    }

    @Override
    public void run(String... args) {
        seedUser("admin", "admin123", "ADMIN");
        seedUser("operator1", "oper123", "OPERATOR");
    }

    private void seedUser(String username, String rawPassword, String role) {
        if (userMapper.findByUsername(username) != null) {
            return;
        }
        User user = new User();
        user.setUsername(username);
        user.setPassword(passwordEncoder.encode(rawPassword));
        user.setRole(role);
        user.setCreatedAt(LocalDateTime.now());
        userMapper.insert(user);
    }
}

package com.instanceguard.platform.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.Base64;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Issues and verifies HS256 bearer tokens signed with the configured
 * {@code jwt.secret}; {@code jwt.expiration} is the token *** in seconds.
 */
@Component
public class JwtUtil {

    private static final String HMAC_ALGORITHM = "HmacSHA256";
    private static final Base64.Encoder B64_ENCODER = Base64.getUrlEncoder().withoutPadding();
    private static final Base64.Decoder B64_DECODER = Base64.getUrlDecoder();
    private static final Pattern STRING_CLAIM = Pattern.compile("\\\"%s\\\"\\s*:\\s*\\\"((?:[^\\\"\\\\]|\\\\.)*)\\\"");
    private static final Pattern NUMBER_CLAIM = Pattern.compile("\\\"%s\\\"\\s*:\\s*(\\d+)");

    private final byte[] secretKey;
    private final long expirationSeconds;

    public JwtUtil(@Value("${jwt.secret}") String secret,
                   @Value("${jwt.expiration}") long expirationSeconds) {
        this.secretKey = secret.getBytes(StandardCharsets.UTF_8);
        this.expirationSeconds = expirationSeconds;
    }

    public String generateToken(String username, String role) {
        long issuedAt = Instant.now().getEpochSecond();
        long expiresAt = issuedAt + expirationSeconds;
        String header = base64Url("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes(StandardCharsets.UTF_8));
        String payload = base64Url(("{\"sub\":" + jsonString(username)
                + ",\"role\":" + jsonString(role)
                + ",\"iat\":" + issuedAt
                + ",\"exp\":" + expiresAt + "}").getBytes(StandardCharsets.UTF_8));
        String unsigned = header + "." + payload;
        return unsigned + "." + base64Url(sign(unsigned));
    }

    public boolean validateToken(String token) {
        return parseClaims(token) != null;
    }

    public String getUsername(String token) {
        String[] parts = verifyAndSplit(token);
        return parts == null ? null : stringClaim(parts[1], "sub");
    }

    public String getRole(String token) {
        String[] parts = verifyAndSplit(token);
        return parts == null ? null : stringClaim(parts[1], "role");
    }

    private String parseClaims(String token) {
        String[] parts = verifyAndSplit(token);
        return parts == null ? null : parts[1];
    }

    private String[] verifyAndSplit(String token) {
        if (token == null) {
            return null;
        }
        String[] parts = token.split("\\.", -1);
        if (parts.length != 3) {
            return null;
        }
        String unsigned = parts[0] + "." + parts[1];
        byte[] expected = sign(unsigned);
        byte[] actual;
        try {
            actual = B64_DECODER.decode(parts[2]);
        } catch (IllegalArgumentException e) {
            return null;
        }
        if (!MessageDigest.isEqual(expected, actual)) {
            return null;
        }
        String payload;
        try {
            payload = new String(B64_DECODER.decode(parts[1]), StandardCharsets.UTF_8);
        } catch (IllegalArgumentException e) {
            return null;
        }
        Long expiresAt = numberClaim(payload, "exp");
        if (expiresAt != null && Instant.now().getEpochSecond() > expiresAt) {
            return null;
        }
        return new String[]{parts[0], payload};
    }

    private byte[] sign(String unsigned) {
        try {
            Mac mac = Mac.getInstance(HMAC_ALGORITHM);
            mac.init(new SecretKeySpec(secretKey, HMAC_ALGORITHM));
            return mac.doFinal(unsigned.getBytes(StandardCharsets.UTF_8));
        } catch (Exception e) {
            throw new IllegalStateException("Unable to sign token", e);
        }
    }

    private static String base64Url(byte[] bytes) {
        return B64_ENCODER.encodeToString(bytes);
    }

    private static String jsonString(String value) {
        if (value == null) {
            return "null";
        }
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '"' -> sb.append("\\\"");
                case '\\' -> sb.append("\\\\");
                case '\n' -> sb.append("\\n");
                case '\r' -> sb.append("\\r");
                case '\t' -> sb.append("\\t");
                default -> sb.append(c);
            }
        }
        return sb.append('"').toString();
    }

    private static String stringClaim(String payload, String name) {
        Matcher matcher = Pattern.compile(String.format(STRING_CLAIM.pattern(), name)).matcher(payload);
        return matcher.find() ? unescape(matcher.group(1)) : null;
    }

    private static Long numberClaim(String payload, String name) {
        Matcher matcher = Pattern.compile(String.format(NUMBER_CLAIM.pattern(), name)).matcher(payload);
        return matcher.find() ? Long.parseLong(matcher.group(1)) : null;
    }

    private static String unescape(String value) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '\\' && i + 1 < value.length()) {
                sb.append(value.charAt(++i));
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}

package com.instanceguard.platform.config;

import com.instanceguard.platform.filter.JwtAuthFilter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final JwtAuthFilter jwtAuthFilter;

    public SecurityConfig(JwtAuthFilter jwtAuthFilter) {
        this.jwtAuthFilter = jwtAuthFilter;
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .csrf(csrf -> csrf.disable())
                .sessionManagement(session ->
                        session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/api/auth/**").permitAll()
                        .anyRequest().authenticated())
                .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}

package com.instanceguard.platform.controller;

import com.instanceguard.platform.dto.ApiResponse;
